import React from "react";
import ReactFlow, {
  Background,
  Controls,
  MiniMap,
} from "reactflow";

import "reactflow/dist/style.css";

function TopologyGraph() {
  /*
   * Temporary topology data.
   *
   * This will eventually come from the FastAPI backend.
   */

  const nodes = [
    {
      id: "kafka",
      position: { x: 50, y: 220 },
      data: {
        label: "Kafka\n20 Partitions",
      },
      type: "default",
    },

    {
      id: "processor",
      position: { x: 350, y: 220 },
      data: {
        label: "Stream Processor\nBytewax / Faust",
      },
      type: "default",
    },

    {
      id: "state",
      position: { x: 680, y: 120 },
      data: {
        label: "RocksDB\nState Store",
      },
      type: "default",
    },

    {
      id: "metrics",
      position: { x: 680, y: 330 },
      data: {
        label: "Prometheus\nMetrics",
      },
      type: "default",
    },
  ];

  const edges = [
    {
      id: "kafka-processor",
      source: "kafka",
      target: "processor",
      animated: true,
    },

    {
      id: "processor-state",
      source: "processor",
      target: "state",
      animated: true,
    },

    {
      id: "processor-metrics",
      source: "processor",
      target: "metrics",
      animated: true,
    },
  ];

  return (
    <ReactFlow
      nodes={nodes}
      edges={edges}
      fitView
      attributionPosition="bottom-left"
    >
      <Background gap={20} size={1} />
      <Controls />
      <MiniMap />
    </ReactFlow>
  );
}

export default TopologyGraph;
